    return res.status(400).json({ error: 'Invalid field: "name" must be a string.' });
  }

  if (name.trim() === '') {
    return res.status(400).json({ error: 'Invalid field: "name" must not be blank.' });
  }

  // Placeholder: persist the new user and return it with a generated id.
  const newUser = { id: Date.now(), name: name.trim() };
  return res.status(201).json(newUser);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

